colors_and_type.css.text:
/*
 * maude — design tokens · "Unified Pro Studio"
 *
 * Authoritative token file. Every specimen in system/maude/preview/ and every
 * canvas that opts into this DS links here. Production code consumes the same values.
 *
 * Direction (locked Stage-4 moodboard, variant B — Zed × Webflow):
 *   Dark-first cool-neutral elevation ladder (hue ~255) framing a dotted infinite
 *   canvas; ONE confident indigo accent (hue 268). Mono is a first-class citizen.
 *   The chrome is a deliberate, integrated instrument — dense but calm — that frames
 *   the canvas without competing with it. Cohesion is the identity: every panel,
 *   inspector and toolbar shares ONE material (same hairlines, radii, elevation).
 *
 * Invariants:
 *   1. prefers-reduced-motion: reduce collapses every duration to 1ms (a11y).
 *   2. Tokens live under documented family prefixes
 *      (--bg-*, --fg-*, --accent*, --border-*, --status-*, --presence-*,
 *       --space-*, --type-*, --lh-*, --radius-*, --shadow-*, --dur-*, --ease-*,
 *       --layout-*, --font-*, --canvas-*).
 *
 * Theme model: dark is the DEFAULT (canvas-browser / studio surface); light is an
 * equal-status secondary (reading / handoff). Both blocks share token shapes.
 */

/* ─────────────────────────────────────────────────────────────────────────
 * DARK — default theme. Applies at :root and under .maude[data-theme="dark"].
 * ───────────────────────────────────────────────────────────────────────── */
:root,
.maude[data-theme="dark"],
.ds[data-theme="dark"] {
  /* ─── Surfaces (deepest → highest) ─── cool-neutral ladder, hue 255 ─────── */
  --bg-0: oklch(0.165 0.012 255);   /* canvas / page bg (deepest)            */
  --bg-1: oklch(0.198 0.012 255);   /* panel / card bg                       */
  --bg-2: oklch(0.232 0.013 255);   /* nested panel / popover / inspector    */
  --bg-3: oklch(0.270 0.013 252);   /* input bg / subtle row hover           */
  --bg-4: oklch(0.310 0.014 252);   /* hover / pressed state                 */

  /* ─── Borders — crisp 1px hairlines carry separation (hairline-mono) ────── */
  --border-subtle:  oklch(0.290 0.012 255);
  --border-default: oklch(0.360 0.013 252);
  --border-strong:  oklch(0.450 0.014 250);

  /* ─── Text ──────────────────────────────────────────────────────────────── */
  --fg-0: oklch(0.955 0.005 250);   /* primary text                          */
  --fg-1: oklch(0.790 0.008 250);   /* secondary text                        */
  --fg-2: oklch(0.660 0.010 250);   /* tertiary / muted — computed 6.2:1 on --bg-0, AA */
  --fg-3: oklch(0.650 0.010 250);   /* quietest text - 4.7:1 on --bg-1..3 (a11y gate) */

  /* ─── Accent (single — confident indigo, hue 268) ─────────────────────────
   * Bright on dark so it reads as text/icons/selection (accent/--bg-0 = 6.4:1).
   * The primary fill therefore takes a DARK --accent-fg (navy), not white
   * (dark-fg/accent = 6.3:1; white/accent would be only 3.0:1). Light theme
   * inverts: darker accent + white fg. */
  --accent:        oklch(0.680 0.180 268);   /* brand accent — text + primary fill */
  --accent-hover:  oklch(0.730 0.170 268);   /* brighter → forward on dark    */
  --accent-active: oklch(0.630 0.180 268);
  --accent-fg:     oklch(0.180 0.030 268);   /* dark navy — text on accent fills */
  --accent-soft:  oklch(0.460 0.110 268);
  --accent-muted: var(--accent-soft);   /* subtle accent border / chip   */
  --selection:   color-mix(in oklab, var(--accent) 16%, transparent);
  --accent-tint: var(--selection); /* selection / active row */

  /* ─── Status ────────────────────────────────────────────────────────────── */
  --status-success: oklch(0.760 0.150 162);
  --status-warn:    oklch(0.800 0.130 78);
  --status-error:   oklch(0.660 0.190 25);
  --status-info:    oklch(0.720 0.120 238);

  /* ─── Presence (collaborators + the AI agent on the canvas) ─────────────── */
  --presence-online:  oklch(0.740 0.160 145);
  --presence-away:    oklch(0.800 0.130 78);
  --presence-offline: oklch(0.560 0.020 255);
  --x-presence-agent:   oklch(0.700 0.190 322);
  --presence-agent: var(--x-presence-agent);   /* AI agent cursor — violet-magenta, held 54° off the indigo accent so it never reads as "the accent" */

  /* ─── Shadows — subtle on dark; hairlines do most of the work ───────────── */
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.40);
  --shadow-md: 0 4px 14px rgba(0, 0, 0, 0.46);
  --shadow-lg: 0 14px 38px rgba(0, 0, 0, 0.56);

  /* ─── Radii — mild, crisp ──────────────────────────────────────────────── */
  --radius-xs: 3px;
  --radius-sm: 5px;
  --radius-md: 7px;
  --radius-lg: 10px;
  --radius-xl: 14px;
  --radius-pill: 999px;

  /* ─── Spacing — dense, 4px base ─────────────────────────────────────────── */
  --space-0: 0;
  --space-1: 2px;
  --space-2: 4px;
  --space-3: 8px;
  --space-4: 12px;
  --space-5: 16px;
  --space-6: 24px;
  --space-7: 32px;
  --space-8: 48px;

  /* ─── Typography ────────────────────────────────────────────────────────── */
  --font-display: "Inter Tight", "Inter", system-ui, -apple-system, sans-serif;
  --font-body:    "Inter", system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono:    "JetBrains Mono", "Geist Mono", ui-monospace, "SF Mono", Menlo, monospace;

  /* Type scale — precise UI ladder, ~1.2 ratio, tightened for dense ──────── */
  --type-xs:   11px;   --lh-xs:   16px;
  --type-sm:   12px;   --lh-sm:   18px;
  --type-base: 14px;   --lh-base: 20px;
  --type-md:   16px;   --lh-md:   24px;
  --type-lg:   19px;   --lh-lg:   26px;
  --type-xl:   23px;   --lh-xl:   30px;
  --type-2xl:  28px;   --lh-2xl:  34px;
  --type-3xl:  34px;   --lh-3xl:  40px;

  /* Numeric fields use tabular figures — set on .mono / inputs in chrome.     */
  --tracking-tight: -0.014em;   /* display headings                          */
  --tracking-wide:   0.04em;    /* mono eyebrows / SKU labels                 */

  /* ─── Motion — crisp, snappy (Zed-fast) ─────────────────────────────────── */
  --dur-flip:  140ms;
  --dur-panel: 220ms;
  --dur-route: 280ms;
  --dur-soft:  120ms;
  --ease-out:    cubic-bezier(0.2, 0, 0, 1);
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);

  /* ─── Canvas (the signature surface — dotted infinite canvas) ───────────── */
  --x-canvas-bg:   var(--bg-0);
  --canvas-bg: var(--x-canvas-bg);
  --x-canvas-dot:  oklch(0.340 0.012 255);
  --canvas-dot: var(--x-canvas-dot);   /* dot-grid colour                 */
  --x-canvas-grid: 24px;
  --canvas-grid: var(--x-canvas-grid);                     /* dot pitch                       */

  /* ─── Layout ────────────────────────────────────────────────────────────── */
  --layout-max-w:  none;            /* app surface, full-bleed                */
  --layout-gutter: var(--space-5);

  /* ─── Schema v1 roles (V2-2.15 bring-up) ─── */
  --accent-on-soft: var(--fg-0); /* text on --accent-soft */
  --accent-text: var(--accent); /* the accent reads as text in both themes */
  --focus-ring: var(--accent); /* _components.css outlines use the accent */
  --focus-ring-width: 2px; /* _components.css outlines are 2px */
  --focus-ring-offset: 1px; /* _components.css .btn offset */
  --scrim: color-mix(in oklch, var(--bg-0) 60%, transparent); /* modal backdrop */
  --status-success-fg: var(--bg-0); /* text on the fill */
  --status-warn-fg: var(--bg-0); /* text on the fill */
  --status-error-fg: var(--bg-0); /* text on the fill */
  --status-info-fg: var(--bg-0); /* text on the fill */
  --status-success-soft: color-mix(in oklch, var(--status-success) 16%, transparent); /* tint, same mix as --selection */
  --status-warn-soft: color-mix(in oklch, var(--status-warn) 16%, transparent); /* tint, same mix as --selection */
  --status-error-soft: color-mix(in oklch, var(--status-error) 16%, transparent); /* tint, same mix as --selection */
  --status-info-soft: color-mix(in oklch, var(--status-info) 16%, transparent); /* tint, same mix as --selection */
  --status-success-text: var(--status-success);
  --status-warn-text: var(--status-warn);
  --status-error-text: var(--status-error);
  --status-info-text: var(--status-info);
  --weight-regular: 400;
  --weight-medium: 500;
  --weight-semibold: 600;
  --weight-bold: 700;
  --tracking-normal: 0;
}

/* ─────────────────────────────────────────────────────────────────────────
 * LIGHT — equal-status secondary theme.
 * ───────────────────────────────────────────────────────────────────────── */
.maude[data-theme="light"],
.ds[data-theme="light"] {
  --bg-0: oklch(0.975 0.004 255);
  --bg-1: oklch(1.000 0 0);
  --bg-2: oklch(0.987 0.003 255);
  --bg-3: oklch(0.955 0.005 255);
  --bg-4: oklch(0.928 0.006 255);

  --border-subtle:  oklch(0.922 0.005 255);
  --border-default: oklch(0.868 0.007 255);
  --border-strong:  oklch(0.780 0.009 255);

  --fg-0: oklch(0.225 0.015 260);
  --fg-1: oklch(0.400 0.014 260);
  --fg-2: oklch(0.510 0.012 260);   /* tertiary — computed 5.35:1 on --bg-0 light, AA */
  --fg-3: oklch(0.520 0.012 260);   /* 4.8:1 on --bg-0..3 */

  --accent:        oklch(0.520 0.195 268);   /* deeper on light for contrast  */
  --accent-hover:  oklch(0.470 0.195 268);
  --accent-active: oklch(0.430 0.190 268);
  --accent-fg:     oklch(0.995 0.004 268);
  --accent-soft:  oklch(0.895 0.050 268);
  --accent-muted: var(--accent-soft);
  --selection:   color-mix(in oklab, var(--accent) 12%, transparent);
  --accent-tint: var(--selection);

  --status-success: oklch(0.560 0.150 162);
  --status-warn:    oklch(0.640 0.140 70);
  --status-error:   oklch(0.560 0.200 25);
  --status-info:    oklch(0.530 0.150 238);

  --presence-online:  oklch(0.560 0.160 145);
  --presence-away:    oklch(0.640 0.140 70);
  --presence-offline: oklch(0.700 0.010 255);
  --x-presence-agent:   oklch(0.520 0.190 322);
  --presence-agent: var(--x-presence-agent);

  --shadow-sm: 0 1px 2px rgba(18, 20, 30, 0.08);
  --shadow-md: 0 4px 14px rgba(18, 20, 30, 0.10);
  --shadow-lg: 0 14px 38px rgba(18, 20, 30, 0.14);

  --x-canvas-bg:  oklch(0.965 0.004 255);
  --canvas-bg: var(--x-canvas-bg);
  --x-canvas-dot: oklch(0.860 0.008 255);

  /* ─── Schema v1 roles (V2-2.15 bring-up) ─── */
  --accent-on-soft: var(--accent-active); /* text on --accent-soft */
  --accent-text: var(--accent); /* the accent reads as text in both themes */
  --focus-ring: var(--accent); /* _components.css outlines use the accent */
  --scrim: color-mix(in oklch, var(--fg-0) 40%, transparent); /* modal backdrop */
  --status-success-fg: var(--accent-fg); /* text on the fill */
  --status-warn-fg: var(--fg-0); /* text on the fill */
  --status-error-fg: var(--accent-fg); /* text on the fill */
  --status-info-fg: var(--accent-fg); /* text on the fill */
  --status-success-soft: color-mix(in oklch, var(--status-success) 12%, transparent); /* tint, same mix as --selection */
  --status-warn-soft: color-mix(in oklch, var(--status-warn) 12%, transparent); /* tint, same mix as --selection */
  --status-error-soft: color-mix(in oklch, var(--status-error) 12%, transparent); /* tint, same mix as --selection */
  --status-info-soft: color-mix(in oklch, var(--status-info) 12%, transparent); /* tint, same mix as --selection */
  --status-success-text: var(--status-success);
  --status-warn-text: var(--status-warn);
  --status-error-text: var(--status-error);
  --status-info-text: var(--status-info);
  --canvas-dot: var(--x-canvas-dot);
}

/* Reduced-motion: collapse durations everywhere (a11y invariant). */
@media (prefers-reduced-motion: reduce) {
  :root,
  .maude[data-theme="dark"],
  .ds[data-theme="dark"],
  .maude[data-theme="light"],
  .ds[data-theme="light"] {
    --dur-flip:  1ms;
    --dur-panel: 1ms;
    --dur-route: 1ms;
    --dur-soft:  1ms;
  }
}

preview/_components.css.text:
/*
 * maude — shared component anatomy · MAUDE/COMPONENTS · "Unified Pro Studio"
 *
 * ONE material across every chrome surface: panels, toolbars, inspectors, layer
 * trees and controls share the same 1px hairlines (--border-default), the same
 * radii (--radius-sm/md), the same elevation tokens. That shared material IS the
 * signature — chrome that frames the canvas without competing with it. Dense.
 *
 * Specimens reference these classes instead of re-implementing the anatomy.
 * The 8 MOTION ROLE CLASSES at the bottom ship verbatim (DDR-049, fixed vocab).
 */

/* ─── Buttons ───────────────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-family: var(--font-body);
  font-size: var(--type-sm);
  font-weight: 500;
  line-height: 1;
  padding: var(--space-3) var(--space-4);     /* dense: 8/12 */
  border: 1px solid var(--border-default);
  border-radius: var(--radius-sm);
  background: var(--bg-2);
  color: var(--fg-0);
  cursor: pointer;
  transition: background var(--dur-soft) var(--ease-out),
              border-color var(--dur-soft) var(--ease-out),
              color var(--dur-soft) var(--ease-out);
}
.btn:hover { background: var(--bg-3); border-color: var(--border-strong); }
.btn:active { background: var(--bg-4); }
.btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.btn:disabled { color: var(--fg-3); cursor: not-allowed; background: var(--bg-1); }

.btn--primary { background: var(--accent); border-color: var(--accent); color: var(--accent-fg); }
.btn--primary:hover { background: var(--accent-hover); border-color: var(--accent-hover); }
.btn--primary:active { background: var(--accent-active); }

.btn--ghost { background: transparent; border-color: transparent; color: var(--fg-1); }
.btn--ghost:hover { background: var(--bg-2); color: var(--fg-0); }

.btn--danger { background: transparent; border-color: var(--border-default); color: var(--status-error); }
.btn--danger:hover { background: color-mix(in oklab, var(--status-error) 14%, transparent); border-color: var(--status-error); }

.btn--icon { padding: var(--space-3); width: 28px; height: 28px; justify-content: center; }
.btn--sm { font-size: var(--type-xs); padding: var(--space-2) var(--space-3); }

/* ─── Keyboard hint ─────────────────────────────────────────────────────── */
.kbd {
  font-family: var(--font-mono);
  font-size: var(--type-xs);
  line-height: 1;
  padding: 3px 6px;
  border: 1px solid var(--border-default);
  border-bottom-width: 2px;
  border-radius: var(--radius-xs);
  background: var(--bg-2);
  color: var(--fg-1);
}

/* ─── Inputs ────────────────────────────────────────────────────────────── */
.input, .select, .textarea {
  font-family: var(--font-body);
  font-size: var(--type-sm);
  color: var(--fg-0);
  background: var(--bg-3);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-sm);
  padding: var(--space-3) var(--space-4);
  width: 100%;
  transition: border-color var(--dur-soft) var(--ease-out), box-shadow var(--dur-soft) var(--ease-out);
}
.input::placeholder, .textarea::placeholder { color: var(--fg-3); }
.input:focus, .select:focus, .textarea:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-tint);
}
.textarea { resize: vertical; min-height: 76px; }

/* Numeric / coordinate field — tabular mono, the inspector's native unit. */
.field {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-size: var(--type-xs);
  color: var(--fg-0);
  background: var(--bg-3);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-xs);
  padding: var(--space-2) var(--space-3);
  width: 64px;
  text-align: right;
}
.field:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-tint); }

/* ─── Segmented control ─────────────────────────────────────────────────── */
.seg {
  display: inline-flex;
  border: 1px solid var(--border-default);
  border-radius: var(--radius-sm);
  overflow: hidden;
  background: var(--bg-2);
}
.seg button {
  appearance: none; border: 0; background: transparent;
  color: var(--fg-2); font-size: var(--type-xs); font-family: var(--font-mono);
  padding: var(--space-2) var(--space-4); cursor: pointer;
}
.seg button[aria-pressed="true"], .seg button[aria-selected="true"] {
  background: var(--bg-4); color: var(--fg-0);
}
.seg button + button { border-left: 1px solid var(--border-subtle); }

/* ─── Switch ────────────────────────────────────────────────────────────── */
.switch {
  appearance: none; position: relative; width: 34px; height: 18px;
  border-radius: var(--radius-pill); background: var(--bg-4);
  border: 1px solid var(--border-default); cursor: pointer;
  transition: background var(--dur-flip) var(--ease-out);
}
.switch::after {
  content: ""; position: absolute; top: 1px; left: 1px; width: 14px; height: 14px;
  border-radius: var(--radius-pill); background: var(--fg-1);
  transition: transform var(--dur-flip) var(--ease-out), background var(--dur-flip) var(--ease-out);
}
.switch:checked { background: var(--accent); border-color: var(--accent); }
.switch:checked::after { transform: translateX(16px); background: var(--accent-fg); }
.switch:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

/* ─── Chips / tags / badges ─────────────────────────────────────────────── */
.chip, .tag {
  display: inline-flex; align-items: center; gap: var(--space-2);
  font-size: var(--type-xs); font-family: var(--font-mono);
  padding: var(--space-1) var(--space-3);
  border: 1px solid var(--border-default); border-radius: var(--radius-pill);
  color: var(--fg-1); background: var(--bg-2);
}
.tag--accent { color: var(--accent); border-color: var(--accent-muted); background: var(--accent-tint); }

/* ─── The unified panel material — the signature ────────────────────────── */
.panel {
  background: var(--bg-1);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}
.panel-hd {
  display: flex; align-items: center; justify-content: space-between;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--border-subtle);
  font-family: var(--font-mono); font-size: var(--type-xs);
  letter-spacing: var(--tracking-wide); text-transform: uppercase; color: var(--fg-2);
}
.panel-bd { padding: var(--space-4); }

/* Toolbar — same material, horizontal. */
.toolbar {
  display: flex; align-items: center; gap: var(--space-3);
  padding: var(--space-2) var(--space-3);
  background: var(--bg-1); border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
}
.toolbar-group { display: flex; align-items: center; gap: var(--space-1); }
.toolbar-sep { width: 1px; align-self: stretch; background: var(--border-subtle); margin: 0 var(--space-2); }

/* Inspector rows — label + tabular field grid. */
.insp-row { display: grid; grid-template-columns: 64px 1fr; align-items: center; gap: var(--space-3); padding: var(--space-2) 0; }
.insp-label { font-family: var(--font-mono); font-size: var(--type-xs); color: var(--fg-2); text-transform: uppercase; letter-spacing: var(--tracking-wide); }
.insp-fields { display: flex; gap: var(--space-2); }

/* Layer tree rows. */
.tree-row {
  display: flex; align-items: center; gap: var(--space-3);
  padding: var(--space-2) var(--space-3); border-radius: var(--radius-xs);
  font-size: var(--type-sm); color: var(--fg-1); cursor: default;
}
.tree-row:hover { background: var(--bg-2); }
.tree-row[aria-selected="true"] { background: var(--accent-tint); color: var(--fg-0); box-shadow: inset 2px 0 0 var(--accent); }

/* ─── Tabs ──────────────────────────────────────────────────────────────── */
.tabbar { display: flex; gap: var(--space-1); border-bottom: 1px solid var(--border-subtle); }
.tab {
  appearance: none; border: 0; background: transparent;
  font-size: var(--type-sm); color: var(--fg-2); font-family: var(--font-body);
  padding: var(--space-3) var(--space-4); cursor: pointer; border-bottom: 2px solid transparent;
}
.tab[aria-selected="true"] { color: var(--fg-0); border-bottom-color: var(--accent); }

/* ─── Callout ───────────────────────────────────────────────────────────── */
.callout {
  display: flex; gap: var(--space-3); padding: var(--space-4);
  border: 1px solid var(--border-default); border-left-width: 3px;
  border-radius: var(--radius-sm); background: var(--bg-1); color: var(--fg-1);
}
.callout--info    { border-left-color: var(--status-info); }
.callout--success { border-left-color: var(--status-success); }
.callout--warn    { border-left-color: var(--status-warn); }
.callout--error   { border-left-color: var(--status-error); }

/* ─── Presence ──────────────────────────────────────────────────────────── */
.presence-dot { width: 8px; height: 8px; border-radius: var(--radius-pill); display: inline-block; }
.presence-dot--online  { background: var(--presence-online); }
.presence-dot--away    { background: var(--presence-away); }
.presence-dot--offline { background: var(--presence-offline); }
.presence-dot--agent   { background: var(--presence-agent); box-shadow: 0 0 0 3px color-mix(in oklab, var(--presence-agent) 28%, transparent); }

/* ─────────────────────────────────────────────────────────────────────────
 * Motion role classes — CSS-only mirror of canvas-lib <MotionDemo role> (DDR-049).
 * Fixed 8-role vocabulary; each loops on first paint (matching loop="always").
 * Reduced-motion handled by the --dur-* token collapse + the killswitch below.
 * ───────────────────────────────────────────────────────────────────────── */
@keyframes motion-flip-kf { 0% { transform: translateY(0); } 100% { transform: translateY(-12px); } }
.motion-flip { animation: motion-flip-kf var(--dur-flip) var(--ease-out) infinite alternate; overflow: hidden; }

@keyframes motion-panel-kf { 0% { transform: translateX(-80px); } 100% { transform: translateX(0); } }
.motion-panel { animation: motion-panel-kf var(--dur-panel) var(--ease-in-out) infinite alternate; overflow: hidden; }

@keyframes motion-route-kf { 0% { opacity: 0; transform: scale(0.92); } 100% { opacity: 1; transform: scale(1); } }
.motion-route { animation: motion-route-kf var(--dur-route) var(--ease-out) infinite alternate; overflow: hidden; }

@keyframes motion-soft-kf { 0% { opacity: 0; } 100% { opacity: 1; } }
.motion-soft { animation: motion-soft-kf var(--dur-soft) var(--ease-out) infinite alternate; }

@keyframes motion-spring-kf { 0% { transform: translateY(0); } 60% { transform: translateY(-20px); } 78% { transform: translateY(-12px); } 90% { transform: translateY(-16px); } 100% { transform: translateY(-14px); } }
.motion-spring { animation: motion-spring-kf var(--dur-panel) cubic-bezier(0.34, 1.56, 0.64, 1) infinite alternate; overflow: hidden; }

@keyframes motion-scroll-kf { 0% { transform: translateX(0); } 100% { transform: translateX(24px); } }
.motion-scroll { animation: motion-scroll-kf var(--dur-route) var(--ease-in-out) infinite alternate; overflow: hidden; }

@keyframes motion-drag-kf { 0% { transform: rotate(0); } 50% { transform: rotate(4deg); } 100% { transform: rotate(0); } }
.motion-drag { animation: motion-drag-kf var(--dur-flip) var(--ease-out) infinite alternate; overflow: hidden; }

@keyframes motion-presence-kf { 0% { opacity: 0; transform: scale(0.9); } 100% { opacity: 1; transform: scale(1); } }
.motion-presence { animation: motion-presence-kf var(--dur-soft) var(--ease-out) infinite alternate; overflow: hidden; max-width: 56px; max-height: 56px; }

:root[data-reduced-motion="true"] [class*="motion-"] { animation: none !important; }

/* ─── Schema v1 class contract (V2-2.15 bring-up) ─────────────────────────────
 * The core components this system had only as specimen classes, lifted verbatim from those
 * specimens (source in each comment) under the schema's class names. Scoped to `.ds` (the
 * <DSRoot> wrapper), so a canvas that names a local class `.dialog` or `.tooltip` under the
 * `.maude` wrapper renders exactly as before. components.json maps every core component;
 * a component this system has no rule for is a declared gap there (null), never invented. */

/* Checkbox ← components-toggles.css .check */
:where(.ds) .checkbox {
  appearance: none;
  flex: none;
  width: 16px;
  height: 16px;
  margin: 0;
  border: 1px solid var(--border-default);
  border-radius: var(--radius-xs);
  background: var(--bg-3);
  cursor: pointer;
  position: relative;
  transition: background var(--dur-flip) var(--ease-out), border-color var(--dur-flip) var(--ease-out);
}
:where(.ds) .checkbox:checked,
:where(.ds) .checkbox:indeterminate {
  background: var(--accent);
  border-color: var(--accent);
}
:where(.ds) .checkbox:checked::after {
  content: "";
  position: absolute;
  left: 5px;
  top: 1px;
  width: 4px;
  height: 8px;
  border: solid var(--accent-fg);
  border-width: 0 1.5px 1.5px 0;
  transform: rotate(42deg);
}
:where(.ds) .checkbox:indeterminate::after {
  content: "";
  position: absolute;
  left: 3px;
  top: 7px;
  width: 8px;
  height: 1.5px;
  background: var(--accent-fg);
}
:where(.ds) .checkbox:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
:where(.ds) .checkbox:disabled { cursor: not-allowed; }

/* Dialog ← components-dialogs.css .dlg (a .panel with elevation) */
:where(.ds) .dialog {
  position: relative;
  box-shadow: var(--shadow-lg);
  z-index: 1;
}

/* Tooltip ← components-tooltips.css .tt-tip */
:where(.ds) .tooltip {
  position: absolute;
  z-index: 5;
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  white-space: nowrap;
  padding: var(--space-2) var(--space-3);
  background: var(--bg-2);
  color: var(--fg-0);
  font-size: var(--type-xs);
  line-height: 1;
  border: 1px solid var(--border-default);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-md);
  pointer-events: none;
}

/* Type roles (<Text role>) — token compositions from the schema registry; no new value. */
:where(.ds) .t-title { font-family: var(--font-display); font-size: var(--type-2xl); line-height: var(--lh-2xl); font-weight: var(--weight-semibold); letter-spacing: var(--tracking-tight); }
:where(.ds) .t-heading { font-family: var(--font-display); font-size: var(--type-xl); line-height: var(--lh-xl); font-weight: var(--weight-semibold); letter-spacing: var(--tracking-tight); }
:where(.ds) .t-subheading { font-family: var(--font-body); font-size: var(--type-lg); line-height: var(--lh-lg); font-weight: var(--weight-medium); letter-spacing: var(--tracking-normal); }
:where(.ds) .t-body { font-family: var(--font-body); font-size: var(--type-base); line-height: var(--lh-base); font-weight: var(--weight-regular); letter-spacing: var(--tracking-normal); }
:where(.ds) .t-body-sm { font-family: var(--font-body); font-size: var(--type-sm); line-height: var(--lh-sm); font-weight: var(--weight-regular); letter-spacing: var(--tracking-normal); }
:where(.ds) .t-caption { font-family: var(--font-body); font-size: var(--type-xs); line-height: var(--lh-xs); font-weight: var(--weight-regular); letter-spacing: var(--tracking-normal); }
:where(.ds) .t-label { font-family: var(--font-body); font-size: var(--type-sm); line-height: var(--lh-sm); font-weight: var(--weight-medium); letter-spacing: var(--tracking-normal); }
:where(.ds) .t-eyebrow { font-family: var(--font-mono); font-size: var(--type-xs); line-height: var(--lh-xs); font-weight: var(--weight-semibold); letter-spacing: var(--tracking-wide); }
:where(.ds) .t-code { font-family: var(--font-mono); font-size: var(--type-sm); line-height: var(--lh-sm); font-weight: var(--weight-regular); letter-spacing: 0; }
:where(.ds) .t-num { font-variant-numeric: tabular-nums; }

